import{_ as n}from"./chunks/pythonnew.Bfm6nFvc.js";import{_ as t,c as a,o,ag as i}from"./chunks/framework.Bzez9NG9.js";const y=JSON.parse('{"title":"Python","description":"Use Python and Jupyter in SPACE for analysis, automation, IBM Planning Analytics development, and secure access to SPACE-managed secrets and connections.","frontmatter":{"title":"Python","description":"Use Python and Jupyter in SPACE for analysis, automation, IBM Planning Analytics development, and secure access to SPACE-managed secrets and connections.","keywords":["Python","Jupyter","automation","IBM Planning Analytics","TM1","TM1py","SPACE Python SDK","secrets","connections","credentials","Git"],"outline":"deep"},"headers":[],"relativePath":"doc/python/index.md","filePath":"doc/python/index.md"}'),s={name:"doc/python/index.md"};function r(c,e,l,d,p,h){return o(),a("div",null,e[0]||(e[0]=[i('<h1 id="python" tabindex="-1">Python <a class="header-anchor" href="#python" aria-label="Permalink to &quot;Python&quot;">​</a></h1><p>SPACE includes an integrated Python and Jupyter environment for analysis, development, and automation. Work with notebooks and Python scripts directly in SPACE, install additional packages, use Git for version control, and run scripts automatically through SPACE jobs.</p><p>Python can also integrate with other parts of SPACE through the <strong>SPACE Python SDK</strong>. Scripts and notebooks can securely access secrets and configured connection information without hard-coding credentials, making it practical to build reusable integrations and automation for IBM Planning Analytics and other systems.</p><p><img src="'+n+'" alt="Python workspace" data-zoomable=""></p><h2 id="scripts-and-notebooks" tabindex="-1">Scripts and notebooks <a class="header-anchor" href="#scripts-and-notebooks" aria-label="Permalink to &quot;Scripts and notebooks&quot;">​</a></h2><p>Use <a href="./scripts.html">Python scripts</a> for reusable programs and automation, including scripts that can be executed through <a href="./../configuration/jobs.html">Jobs</a>.</p><p>Use <a href="./jupyter.html">Jupyter</a> for interactive analysis and development, where you can run code incrementally, inspect results, and combine code with explanatory content.</p><p>The Python workspace includes a file browser and launcher for working with scripts, notebooks, folders, consoles, and other files.</p><h2 id="space-python-sdk" tabindex="-1">SPACE Python SDK <a class="header-anchor" href="#space-python-sdk" aria-label="Permalink to &quot;SPACE Python SDK&quot;">​</a></h2><p>The <a href="./sdk.html">SPACE Python SDK</a> provides a Python interface to supported SPACE capabilities from scripts and notebooks.</p><p>It can be used to access SPACE-managed resources without embedding SPACE API calls or authentication details directly in your code. Authentication to SPACE is provided automatically to Python executions through the SPACE environment.</p><p>This provides a foundation for Python workflows that need to work with centrally managed configuration while remaining portable between SPACE environments.</p><h2 id="secrets-and-connections" tabindex="-1">Secrets and connections <a class="header-anchor" href="#secrets-and-connections" aria-label="Permalink to &quot;Secrets and connections&quot;">​</a></h2><p>SPACE administrators can securely store credentials and other sensitive values as <strong>secrets</strong> and configure reusable <strong>connections</strong> for external systems.</p><p>Python code can access these through the SPACE Python SDK. This avoids storing passwords, API keys, or other credentials directly in notebooks, scripts, Git repositories, or configuration files.</p><p>For example, a script can retrieve:</p><ul><li>a named secret containing credentials or API keys;</li><li>the configuration for a SPACE connection;</li><li>connection authentication information needed by a Python client library.</li></ul><p>Use <code>from space import secrets, connections</code> to access these resources. See <a href="./secrets-and-connections.html">Secrets and connections</a> for the SDK methods and usage patterns.</p><h2 id="ibm-planning-analytics-and-tm1py" tabindex="-1">IBM Planning Analytics and TM1py <a class="header-anchor" href="#ibm-planning-analytics-and-tm1py" aria-label="Permalink to &quot;IBM Planning Analytics and TM1py&quot;">​</a></h2><p><a href="./tm1py.html">TM1py</a> can be used in SPACE scripts and notebooks to work programmatically with IBM Planning Analytics.</p><p>Combined with SPACE-managed connections and secrets, TM1py code can obtain the required connection configuration and credentials at runtime instead of maintaining them separately in Python files.</p><p>This is useful for custom Planning Analytics analysis, administration, development, and automation that goes beyond the built-in SPACE tools.</p><h2 id="custom-packages" tabindex="-1">Custom packages <a class="header-anchor" href="#custom-packages" aria-label="Permalink to &quot;Custom packages&quot;">​</a></h2><p>Additional Python libraries can be made available in the SPACE Python environment when a workflow requires packages that are not included by default.</p><p>See <a href="./custom-packages.html">Custom packages</a> for installation and package-management options.</p><h2 id="git" tabindex="-1">Git <a class="header-anchor" href="#git" aria-label="Permalink to &quot;Git&quot;">​</a></h2><p>SPACE includes Git support for Python development so client scripts, notebooks, and related files can be maintained in a Git repository using the JupyterLab Git extension.</p><p>Python Git is separate from the <a href="./../planning-analytics/git.html">Planning Analytics Git integration</a>, which is designed for Planning Analytics model assets.</p><p>See <a href="./git.html">Git</a> for repository setup and configuration.</p><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><p><a href="./examples.html">Python examples</a> brings the individual capabilities together in practical workflows.</p><p>Examples include using the SPACE Python SDK, retrieving secrets and connection configuration, connecting to Planning Analytics with TM1py, and combining these capabilities in reusable scripts and notebooks.</p><p>The individual feature pages also include focused code snippets where they are most useful, while the Examples page is intended for more complete end-to-end workflows.</p>',33)]))}const P=t(s,[["render",r]]);export{y as __pageData,P as default};
